import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[32768];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') {
                    throw new IOException();
                }
                res = res * 10 + (c - '0');
                c = read();
            }
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        int n = sc.nextInt();
        if (n == -1) return;
        int m = sc.nextInt();

        int[] t = new int[m];
        long currentSize = n;
        for (int i = 0; i < m; i++) {
            t[i] = sc.nextInt();
            currentSize -= currentSize / t[i];
        }

        int count = (int) Math.min(currentSize, 10000L);
        if (count <= 0) {
            return;
        }

        int[] pos = new int[count];
        for (int i = 0; i < count; i++) {
            pos[i] = i + 1;
        }

        for (int i = m - 1; i >= 0; i--) {
            int div = t[i] - 1;
            for (int j = 0; j < count; j++) {
                pos[j] += (pos[j] - 1) / div;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count; i++) {
            sb.append(pos[i]).append('\n');
            if (sb.length() > 65536) {
                System.out.print(sb.toString());
                sb.setLength(0);
            }
        }
        if (sb.length() > 0) {
            System.out.print(sb.toString());
        }
    }
}
